CREATE TABLE case_map_areas (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, area_type TEXT NOT NULL CHECK (area_type IN ('search','searched','risk','rally')), status TEXT NOT NULL CHECK (status IN ('candidate','pending_review','approved','rejected')), title TEXT NOT NULL, description TEXT NULL, task_id TEXT NULL REFERENCES tasks(id) ON DELETE SET NULL, clue_id TEXT NULL REFERENCES clues(id) ON DELETE SET NULL, version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0), created_by_user_id TEXT NOT NULL REFERENCES users(id), reviewed_by_user_id TEXT NULL REFERENCES users(id), reviewed_at TEXT NULL, starts_at TEXT NULL, ends_at TEXT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
-- statement-break
CREATE INDEX idx_case_map_areas_case_status ON case_map_areas(case_id, status, updated_at);
-- statement-break
CREATE TABLE case_map_area_vertices (area_id TEXT NOT NULL REFERENCES case_map_areas(id) ON DELETE CASCADE, vertex_order INTEGER NOT NULL CHECK (vertex_order >= 0), latitude REAL NOT NULL CHECK (latitude BETWEEN -90 AND 90), longitude REAL NOT NULL CHECK (longitude BETWEEN -180 AND 180), PRIMARY KEY(area_id, vertex_order));
